SELECT T.ID, T.RES_NAME, T.ORDER_NO, T.PARENT_ID, T.RES_PATH, T.RES_LEVEL, T.ICON, T.METHOD, T.RES_TYPE, T.HIDDEN, T.RES_MODE
FROM LA_RESOURCES T
WHERE T.IS_DEV = 0

    AND T.id IN (
    SELECT DISTINCT T2.RESOURCE_ID FROM LA_ROLE_RESOURCES T2 WHERE T2.AUTHORITY IN
    #{item}
    )


    AND T.id IN
    #{item}

ORDER BY T.RES_LEVEL, T.ORDER_NO

